insert into public.rooms (unit_id, code, name, block, floor, capacity, room_type, has_projector, has_air_conditioning, has_computer, status, notes, seats_count, has_audio_system, has_tv, has_whiteboard, has_interactive_screen, furniture_type, quality_tier, usage_restriction)
select target_unit.id, source_rooms.*
from target_unit cross join source_rooms
where not exists (
  select 1 from public.rooms existing
  where existing.unit_id = target_unit.id and existing.code = source_rooms.code
);

select count(*) as imported_or_existing_rooms
from public.rooms
where unit_id = (select id from public.units where code = 'UNIG-NI' limit 1);
